path = r'c:\Users\amyak\Desktop\gatepass_backend\backend\routes\admin.py'
with open(path, 'a') as f:
    f.write('\n\n# ====================================================\n# REJECT PASS\n# ====================================================\n@router.put("/reject/{pass_id}")\ndef reject_pass(pass_id: int, db: Session = Depends(get_db), user=Depends(get_current_user)):\n    admin_only(user)\n    gp = db.query(Pass).filter(Pass.id == pass_id).first()\n    if not gp: raise HTTPException(status_code=404, detail="Pass not found")\n    if gp.status != "PENDING": raise HTTPException(status_code=400, detail="Already processed")\n    gp.status = "REJECTED"\n    db.commit()\n    return {"message": "Pass rejected"}\n\n# ====================================================\n# DELETE PASS\n# ====================================================\n@router.delete("/delete/{pass_id}")\ndef delete_pass(pass_id: int, db: Session = Depends(get_db), user=Depends(get_current_user)):\n    admin_only(user)\n    gp = db.query(Pass).filter(Pass.id == pass_id).first()\n    if not gp: raise HTTPException(status_code=404, detail="Pass not found")\n    db.delete(gp)\n    db.commit()\n    return {"message": "Pass deleted successfully"}\n')
print("Admin routes appended successfully.")
